package com.arcvitals;

import java.util.Arrays;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.itemstats.ItemStatPlugin;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class PluginDescriptorTest {
    @Test
    public void descriptorNameAndDescription() {
        PluginDescriptor d = ArcVitalsPlugin.class.getAnnotation(PluginDescriptor.class);
        assertEquals("Arc Vitals", d.name());
        assertEquals("An IceHUD inspired Vitals HUD", d.description());
    }

    @Test
    public void declaresItemStatsDependency() {
        // The restore preview injects ItemStatChangesService, which Item Stats binds privately.
        // Without this dependency the plugin's injector cannot resolve it and fails to load.
        PluginDependency[] deps = ArcVitalsPlugin.class.getAnnotationsByType(PluginDependency.class);
        boolean dependsOnItemStats = Arrays.stream(deps).anyMatch(d -> d.value() == ItemStatPlugin.class);
        assertTrue("ArcVitalsPlugin must declare @PluginDependency(ItemStatPlugin.class)", dependsOnItemStats);
    }
}

package com.arcvitals;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.plugins.itemstats.ItemStatChangesService;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.anyLong;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class ArcVitalsOverlayTest {

    private Client client;
    private ArcVitalsConfig config;
    private HudDragController dragController;
    private TargetTracker targetTracker;
    private SwingTracker swingTracker;
    private ArcVitalsOverlay overlay;
    private Graphics2D graphics;

    // Sensible non-degenerate layout values so any geometry actually built during render() is real
    // (no NaN from a zero-size arc). Plain Mockito mocks otherwise return 0/false/null for every
    // config method, ignoring the interface's own @ConfigItem defaults.
    @Before
    public void setUp() {
        client = mock(Client.class);
        config = mock(ArcVitalsConfig.class);
        ItemStatChangesService itemStatService = mock(ItemStatChangesService.class);
        CombatTracker combatTracker = mock(CombatTracker.class);
        SpriteManager spriteManager = mock(SpriteManager.class);
        dragController = mock(HudDragController.class);
        targetTracker = mock(TargetTracker.class);
        swingTracker = mock(SwingTracker.class);

        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
        when(client.getLocalPlayer()).thenReturn(mock(Player.class));

        when(config.size()).thenReturn(150);
        when(config.thickness()).thenReturn(12);
        when(config.gap()).thenReturn(88);
        when(config.barSpacing()).thenReturn(7);
        when(config.curve()).thenReturn(120);
        when(config.barPattern()).thenReturn(BarPattern.NONE);
        when(config.fillStyle()).thenReturn(FillStyle.SMOOTH);
        when(config.segments()).thenReturn(14);
        when(config.trackColor()).thenReturn(new Color(0, 0, 0, 130));
        when(config.baseOpacity()).thenReturn(60);

        overlay = new ArcVitalsOverlay(client, config, itemStatService, combatTracker, spriteManager,
            dragController, targetTracker, swingTracker);

        BufferedImage image = new BufferedImage(765, 503, BufferedImage.TYPE_INT_ARGB);
        graphics = image.createGraphics();
    }

    @Test
    public void rendersOverThePlayerButUnderInterfaces() {
        assertEquals(OverlayLayer.UNDER_WIDGETS, overlay.getLayer());
    }

    @Test
    public void keepsDynamicPositioning() {
        assertEquals(OverlayPosition.DYNAMIC, overlay.getPosition());
    }

    @Test
    public void swingTimerRendersWithoutError() {
        when(config.swingEnabled()).thenReturn(true);
        when(config.swingPlacement()).thenReturn(SwingPlacement.TOP);
        when(config.swingColor()).thenReturn(new java.awt.Color(210, 235, 248));
        when(config.swingSide()).thenReturn(Side.LEFT);
        when(config.showSwingTicks()).thenReturn(true);
        when(config.swingOffsetX()).thenReturn(0);
        when(config.swingOffsetY()).thenReturn(0);
        when(swingTracker.showing(anyInt())).thenReturn(true);
        when(swingTracker.fraction(anyLong())).thenReturn(0.55);
        when(swingTracker.ready(anyLong())).thenReturn(false);
        when(swingTracker.cooldownTicks()).thenReturn(4);

        // Should draw the swing timer without throwing, even with vitals disabled.
        overlay.render(graphics);
    }

    @Test
    public void swingTimerNestedRendersWithoutError() {
        when(config.swingEnabled()).thenReturn(true);
        when(config.swingPlacement()).thenReturn(SwingPlacement.NESTED);
        when(config.swingColor()).thenReturn(new java.awt.Color(210, 235, 248));
        when(config.swingSide()).thenReturn(Side.LEFT);
        when(config.showSwingTicks()).thenReturn(true);
        when(swingTracker.showing(anyInt())).thenReturn(true);
        when(swingTracker.fraction(anyLong())).thenReturn(0.3);
        when(swingTracker.ready(anyLong())).thenReturn(false);
        when(swingTracker.cooldownTicks()).thenReturn(5);

        overlay.render(graphics);
    }

    // Stubs everything drawVital reads on the hitpoints path, boosted to 117 / 99, so a full render()
    // actually draws the HP bar. Overheal on/off is left to each test.
    private void stubBoostedHp() {
        when(client.getCanvasWidth()).thenReturn(765);
        when(client.getCanvasHeight()).thenReturn(503);
        when(client.getVarpValue(anyInt())).thenReturn(0);
        when(client.getRealSkillLevel(Skill.HITPOINTS)).thenReturn(99);
        when(client.getBoostedSkillLevel(Skill.HITPOINTS)).thenReturn(117);

        when(config.hpEnabled()).thenReturn(true);
        when(config.hpColor()).thenReturn(new Color(0, 200, 0));
        when(config.hpThreshold()).thenReturn(0);
        when(config.hpSide()).thenReturn(Side.LEFT);
        when(config.hpShapeOverride()).thenReturn(ShapeOverride.INHERIT);
        when(config.hpFillOverride()).thenReturn(FillStyleOverride.INHERIT);
        when(config.hpPatternOverride()).thenReturn(PatternOverride.INHERIT);
        when(config.barShape()).thenReturn(BarShape.ARC);
        when(config.alertMode()).thenReturn(AlertMode.OFF);
        when(config.alertOpacity()).thenReturn(100);
        when(config.fillDirection()).thenReturn(FillDirection.BOTTOM_UP);
        when(config.valueDisplay()).thenReturn(ValueDisplay.OFF);
    }

    private static int cyanBandCount(BufferedImage img) {
        int n = 0;
        for (int x = 0; x < img.getWidth(); x++) {
            for (int y = 0; y < img.getHeight(); y++) {
                int argb = img.getRGB(x, y);
                int a = (argb >>> 24) & 0xFF;
                int r = (argb >> 16) & 0xFF;
                int gr = (argb >> 8) & 0xFF;
                int b = argb & 0xFF;
                if (a > 120 && gr > 150 && b > 150 && r < 160) {
                    n++;
                }
            }
        }
        return n;
    }

    @Test
    public void overhealBandRendersForBoostedHp() {
        stubBoostedHp();
        when(config.overhealEnabled()).thenReturn(true);
        when(config.overhealColor()).thenReturn(new Color(120, 240, 255, 235));
        when(config.showOverhealTick()).thenReturn(true);

        BufferedImage image = new BufferedImage(765, 503, BufferedImage.TYPE_INT_ARGB);
        overlay.render(image.createGraphics());

        assertTrue("boosted HP should draw an overheal band", cyanBandCount(image) > 0);
    }

    @Test
    public void noOverhealBandWhenDisabled() {
        stubBoostedHp();
        when(config.overhealEnabled()).thenReturn(false);

        BufferedImage image = new BufferedImage(765, 503, BufferedImage.TYPE_INT_ARGB);
        overlay.render(image.createGraphics());

        assertEquals("disabled overheal draws no band", 0, cyanBandCount(image));
    }

    @Test
    public void debugAnimatePrayerIconsRenderWithoutError() {
        when(client.getCanvasWidth()).thenReturn(765);
        when(client.getCanvasHeight()).thenReturn(503);
        when(config.debugEnabled()).thenReturn(true);
        when(config.debugAnimate()).thenReturn(true);
        when(config.debugHpPercent()).thenReturn(50);
        when(config.debugPrayerPercent()).thenReturn(50);
        when(config.debugSpecPercent()).thenReturn(50);
        when(config.debugRunPercent()).thenReturn(50);
        when(config.debugPoisonState()).thenReturn(HpStatus.NONE);
        when(config.hpEnabled()).thenReturn(true);
        when(config.hpColor()).thenReturn(new Color(0, 200, 0));
        when(config.hpThreshold()).thenReturn(0);
        when(config.hpSide()).thenReturn(Side.LEFT);
        when(config.hpShapeOverride()).thenReturn(ShapeOverride.INHERIT);
        when(config.hpFillOverride()).thenReturn(FillStyleOverride.INHERIT);
        when(config.hpPatternOverride()).thenReturn(PatternOverride.INHERIT);
        when(config.barShape()).thenReturn(BarShape.ARC);
        when(config.alertMode()).thenReturn(AlertMode.OFF);
        when(config.fillDirection()).thenReturn(FillDirection.BOTTOM_UP);
        when(config.valueDisplay()).thenReturn(ValueDisplay.OFF);
        when(config.showPrayerIcons()).thenReturn(true);
        when(config.debugPrayerIcons()).thenReturn(3);
        when(config.prayerIconSize()).thenReturn(24);
        when(config.prayerIconOffset()).thenReturn(6);
        when(config.prayerIconSpacing()).thenReturn(2);
        when(config.prayerIconBackground()).thenReturn(false);

        overlay.render(graphics); // must not throw with animate + debug prayer icons on
    }

    @Test
    public void debugPrayerIconChipDrawsWhenEnabled() {
        stubDebugBase();
        stubPrayerIconChip();
        when(config.showPrayerIcons()).thenReturn(true);
        when(config.debugPrayerIcons()).thenReturn(3);

        BufferedImage img = new BufferedImage(765, 503, BufferedImage.TYPE_INT_ARGB);
        overlay.render(img.createGraphics());

        assertTrue("debug prayer-icon row should draw its background chip", magentaCount(img) > 0);
    }

    @Test
    public void prayerIconsHiddenInDebugWhenToggleOff() {
        stubDebugBase();
        stubPrayerIconChip();
        when(config.showPrayerIcons()).thenReturn(false);
        when(config.debugPrayerIcons()).thenReturn(8);

        BufferedImage img = new BufferedImage(765, 503, BufferedImage.TYPE_INT_ARGB);
        overlay.render(img.createGraphics());

        // Show prayer icons is off, so the debug icon row (and its chip) must not draw at all.
        assertEquals("Show prayer icons off -> no debug icon row", 0, magentaCount(img));
    }

    // debugEnabled with one enabled HP vital and neutral appearance, so a debug render draws. Per-element
    // preview stubs (prayer icons / target / swing) are layered on by each test.
    private void stubDebugBase() {
        when(client.getCanvasWidth()).thenReturn(765);
        when(client.getCanvasHeight()).thenReturn(503);
        when(config.debugEnabled()).thenReturn(true);
        when(config.debugHpPercent()).thenReturn(50);
        when(config.debugPrayerPercent()).thenReturn(50);
        when(config.debugSpecPercent()).thenReturn(50);
        when(config.debugRunPercent()).thenReturn(50);
        when(config.debugPoisonState()).thenReturn(HpStatus.NONE);
        when(config.hpEnabled()).thenReturn(true);
        when(config.hpColor()).thenReturn(new Color(0, 200, 0));
        when(config.hpThreshold()).thenReturn(0);
        when(config.hpSide()).thenReturn(Side.LEFT);
        when(config.hpShapeOverride()).thenReturn(ShapeOverride.INHERIT);
        when(config.hpFillOverride()).thenReturn(FillStyleOverride.INHERIT);
        when(config.hpPatternOverride()).thenReturn(PatternOverride.INHERIT);
        when(config.barShape()).thenReturn(BarShape.ARC);
        when(config.alertMode()).thenReturn(AlertMode.OFF);
        when(config.fillDirection()).thenReturn(FillDirection.BOTTOM_UP);
        when(config.valueDisplay()).thenReturn(ValueDisplay.OFF);
    }

    // A distinctive magenta prayer-icon background chip whose pixels can be counted; the chip draws via
    // fillRoundRect regardless of the (mock) SpriteManager, unlike the icon sprites themselves.
    private void stubPrayerIconChip() {
        when(config.prayerIconSize()).thenReturn(24);
        when(config.prayerIconOffset()).thenReturn(6);
        when(config.prayerIconSpacing()).thenReturn(2);
        when(config.prayerIconBackground()).thenReturn(true);
        when(config.prayerIconBackgroundColor()).thenReturn(new Color(255, 0, 255));
    }

    private static int magentaCount(BufferedImage img) {
        int n = 0;
        for (int x = 0; x < img.getWidth(); x++) {
            for (int y = 0; y < img.getHeight(); y++) {
                int argb = img.getRGB(x, y);
                int a = (argb >>> 24) & 0xFF;
                int r = (argb >> 16) & 0xFF;
                int g = (argb >> 8) & 0xFF;
                int b = argb & 0xFF;
                if (a > 40 && r > 150 && g < 90 && b > 150) {
                    n++;
                }
            }
        }
        return n;
    }

    // Target-red pixel count, mirroring magentaCount/cyanBandCount: counts pixels close to the target
    // bar's fill colour so a synthetic debug preview can be proven to have painted (or not).
    private static int redCount(BufferedImage img) {
        int n = 0;
        for (int x = 0; x < img.getWidth(); x++) {
            for (int y = 0; y < img.getHeight(); y++) {
                int argb = img.getRGB(x, y);
                int a = (argb >>> 24) & 0xFF;
                int r = (argb >> 16) & 0xFF;
                int g = (argb >> 8) & 0xFF;
                int b = argb & 0xFF;
                if (a > 40 && r > 150 && g < 90 && b < 90) {
                    n++;
                }
            }
        }
        return n;
    }

    @Test
    public void debugTargetBarRendersWhenEnabled() {
        stubDebugBase();
        when(config.targetBarEnabled()).thenReturn(true);
        when(config.targetBarColor()).thenReturn(new Color(200, 40, 40));
        when(config.targetBarLabel()).thenReturn(TargetLabel.PERCENT_ONLY);
        when(config.targetBarSide()).thenReturn(Side.RIGHT);
        when(config.targetBarShapeOverride()).thenReturn(ShapeOverride.INHERIT);
        when(config.targetBarOffsetX()).thenReturn(0);
        when(config.targetBarOffsetY()).thenReturn(0);
        when(config.debugTargetPercent()).thenReturn(60);
        when(targetTracker.current()).thenReturn(null); // no real target

        BufferedImage img = new BufferedImage(765, 503, BufferedImage.TYPE_INT_ARGB);
        overlay.render(img.createGraphics());
        assertTrue("synthetic target bar should paint", redCount(img) > 0);
    }

    @Test
    public void debugTargetBarHiddenWhenToggleOff() {
        stubDebugBase();
        when(config.targetBarEnabled()).thenReturn(false);
        when(config.debugTargetPercent()).thenReturn(60);
        when(targetTracker.current()).thenReturn(null);

        BufferedImage img = new BufferedImage(765, 503, BufferedImage.TYPE_INT_ARGB);
        overlay.render(img.createGraphics());
        assertEquals("no target bar when Show target bar is off", 0, redCount(img));
    }

    @Test
    public void debugSwingTimerRendersWhenEnabled() {
        stubDebugBase();
        when(config.swingEnabled()).thenReturn(true);
        when(config.swingColor()).thenReturn(new Color(210, 235, 248));
        when(config.swingPlacement()).thenReturn(SwingPlacement.TOP);
        when(config.swingSide()).thenReturn(Side.LEFT);
        when(config.showSwingTicks()).thenReturn(true);
        when(config.swingOffsetX()).thenReturn(0);
        when(config.swingOffsetY()).thenReturn(0);
        when(swingTracker.showing(anyInt())).thenReturn(false); // no real swing
        when(swingTracker.cooldownTicks()).thenReturn(4);

        BufferedImage img = new BufferedImage(765, 503, BufferedImage.TYPE_INT_ARGB);
        overlay.render(img.createGraphics()); // must draw the looping swing without a real swing
    }

    @Test
    public void debugSwingTimerHiddenWhenToggleOff() {
        stubDebugBase();
        when(config.swingEnabled()).thenReturn(false);
        when(swingTracker.showing(anyInt())).thenReturn(false);

        BufferedImage img = new BufferedImage(765, 503, BufferedImage.TYPE_INT_ARGB);
        overlay.render(img.createGraphics());
        // Show swing timer is off: swingShowing is false regardless of debug, so drawSwingTimer /
        // drawSwingNested (and the synthetic loop) never run at all -- deterministic, unlike the
        // "renders" case above whose fill depends on wall-clock timing.
        assertEquals("no swing arc when Show swing timer is off", 0, swingColorCount(img));
    }

    // Swing-colour pixel count for the light blue-white swing fill (210, 235, 248), distinct from the
    // green HP bar, magenta prayer chip, and red target bar used elsewhere in this test class.
    private static int swingColorCount(BufferedImage img) {
        int n = 0;
        for (int x = 0; x < img.getWidth(); x++) {
            for (int y = 0; y < img.getHeight(); y++) {
                int argb = img.getRGB(x, y);
                int a = (argb >>> 24) & 0xFF;
                int r = (argb >> 16) & 0xFF;
                int g = (argb >> 8) & 0xFF;
                int b = argb & 0xFF;
                if (a > 40 && r > 180 && g > 200 && b > 220) {
                    n++;
                }
            }
        }
        return n;
    }
}

package com.arcvitals;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import org.junit.Test;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.assertEquals;

public class FillStyleTest {

    private static final Color FILL = new Color(0, 200, 0);

    private static Geometry left() {
        return new ArcGeometry(200, 200, 140, 12, 70, 4, 110, 0, true, true);
    }

    @Test
    public void smoothPaintsInsideBodyOnly() {
        Geometry geo = left();
        BufferedImage img = render(geo, FillStyle.SMOOTH, FillDirection.BOTTOM_UP, 0.5, FILL);
        Rectangle b = geo.body().getBounds();
        int painted = 0;
        for (int x = 0; x < img.getWidth(); x++) {
            for (int y = 0; y < img.getHeight(); y++) {
                if (opaque(img, x, y)) {
                    painted++;
                    assertTrue("painted pixel outside body bounds at " + x + "," + y,
                        x >= b.x - 2 && x <= b.x + b.width + 2 && y >= b.y - 2 && y <= b.y + b.height + 2);
                }
            }
        }
        assertTrue("smooth should paint some pixels", painted > 0);
    }

    @Test
    public void gradientIsBrighterAtTheAnchorEnd() {
        Geometry geo = left();
        BufferedImage img = render(geo, FillStyle.GRADIENT, FillDirection.BOTTOM_UP, 1.0, FILL);
        double[] bottom = geo.pointAt(0.05); // near the anchored (bottom) end
        double[] top = geo.pointAt(0.95);    // near the far (top) end
        int atBottom = avgBrightness(img, (int) bottom[0], (int) bottom[1], 3);
        int atTop = avgBrightness(img, (int) top[0], (int) top[1], 3);
        assertTrue("both ends should be painted", atBottom >= 0 && atTop >= 0);
        assertTrue("anchor end brighter than far end", atBottom > atTop);
    }

    @Test
    public void glossIsBrighterOnTheCentrelineThanTheEdge() {
        Geometry geo = left();
        BufferedImage img = render(geo, FillStyle.GLOSS, FillDirection.BOTTOM_UP, 1.0, FILL);
        double[] mid = geo.pointAt(0.5);
        double[] n = geo.normalAt(0.5);
        int t = geo.thickness();
        int edgeX = (int) (mid[0] + n[0] * (t / 2.0 - 1));
        int edgeY = (int) (mid[1] + n[1] * (t / 2.0 - 1));
        int centre = avgBrightness(img, (int) mid[0], (int) mid[1], 1);
        int edge = avgBrightness(img, edgeX, edgeY, 1);
        assertTrue("centreline and edge both painted", centre >= 0 && edge >= 0);
        assertTrue("gloss highlight brighter at centre", centre > edge);
    }

    @Test
    public void segmentedLeavesGapsAlongTheFilledSpan() {
        Geometry geo = left();
        BufferedImage img = render(geo, FillStyle.SEGMENTED, FillDirection.BOTTOM_UP, 1.0, FILL);
        boolean sawPip = false;
        boolean sawGap = false;
        for (int i = 1; i < 40; i++) {
            double f = i / 40.0;
            double[] p = geo.pointAt(f);
            if (opaque(img, (int) p[0], (int) p[1])) {
                sawPip = true;
            } else {
                sawGap = true;
            }
        }
        assertTrue("segmented should paint some pips", sawPip);
        assertTrue("segmented should leave some gaps", sawGap);
    }

    @Test
    public void glowHasABrightCoreAlongTheCentreline() {
        Geometry geo = left();
        BufferedImage img = render(geo, FillStyle.GLOW, FillDirection.BOTTOM_UP, 1.0, FILL);
        double[] mid = geo.pointAt(0.5);
        double[] n = geo.normalAt(0.5);
        int t = geo.thickness();
        int edgeX = (int) (mid[0] + n[0] * (t / 2.0 - 1));
        int edgeY = (int) (mid[1] + n[1] * (t / 2.0 - 1));
        int core = avgBrightness(img, (int) mid[0], (int) mid[1], 1);
        int edge = avgBrightness(img, edgeX, edgeY, 1);
        assertTrue("core and edge painted", core >= 0 && edge >= 0);
        assertTrue("glow core brighter than edge", core > edge);
    }

    @Test
    public void notchedDarkensTheMidlineTick() {
        Geometry geo = left();
        BufferedImage img = render(geo, FillStyle.NOTCHED, FillDirection.BOTTOM_UP, 1.0, FILL);
        double[] tick = geo.pointAt(0.5);   // a tick sits here
        double[] plain = geo.pointAt(0.4);  // plain fill here
        int atTick = minBrightness(img, (int) tick[0], (int) tick[1], 2);
        int atPlain = avgBrightness(img, (int) plain[0], (int) plain[1], 1);
        assertTrue("both sampled", atTick >= 0 && atPlain >= 0);
        assertTrue("tick darker than plain fill", atTick < atPlain);
    }

    @Test
    public void segmentedPipCountFollowsContext() {
        CountingGeometry geo = new CountingGeometry(left());
        BufferedImage img = new BufferedImage(400, 400, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = img.createGraphics();
        FillStyle.SEGMENTED.paint(g, geo, FillDirection.BOTTOM_UP, 1.0, new FillContext(FILL, FILL, 7));
        g.dispose();
        assertEquals("one fillRegion call per pip at 100%", 7, geo.fillRegionCalls);
    }

    // Minimum (r+g+b) over opaque pixels in a box; -1 if none opaque.
    private static int minBrightness(BufferedImage img, int x, int y, int rad) {
        int min = Integer.MAX_VALUE;
        for (int dx = -rad; dx <= rad; dx++) {
            for (int dy = -rad; dy <= rad; dy++) {
                if (!opaque(img, x + dx, y + dy)) {
                    continue;
                }
                int argb = img.getRGB(x + dx, y + dy);
                int b = ((argb >> 16) & 0xFF) + ((argb >> 8) & 0xFF) + (argb & 0xFF);
                if (b < min) {
                    min = b;
                }
            }
        }
        return min == Integer.MAX_VALUE ? -1 : min;
    }

    // Wraps a real Geometry and counts fillRegion calls so we can assert the Segmented pip count.
    private static final class CountingGeometry implements Geometry {
        private final Geometry inner;
        int fillRegionCalls;

        CountingGeometry(Geometry inner) {
            this.inner = inner;
        }

        @Override
        public java.awt.Shape body() {
            return inner.body();
        }

        @Override
        public java.awt.geom.Area fillRegion(double lo, double hi, FillDirection dir) {
            fillRegionCalls++;
            return inner.fillRegion(lo, hi, dir);
        }

        @Override
        public java.awt.Shape centerline() {
            return inner.centerline();
        }

        @Override
        public int thickness() {
            return inner.thickness();
        }

        @Override
        public double[] pointAt(double f) {
            return inner.pointAt(f);
        }

        @Override
        public double[] normalAt(double f) {
            return inner.normalAt(f);
        }
    }

    // ---- shared helpers (reused by Tasks 6-10) ----

    static BufferedImage render(Geometry geo, FillStyle style, FillDirection dir, double frac, Color color) {
        BufferedImage img = new BufferedImage(400, 400, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = img.createGraphics();
        style.paint(g, geo, dir, frac, new FillContext(color, color, 14));
        g.dispose();
        return img;
    }

    static boolean opaque(BufferedImage img, int x, int y) {
        if (x < 0 || y < 0 || x >= img.getWidth() || y >= img.getHeight()) {
            return false;
        }
        return (img.getRGB(x, y) >>> 24) > 20;
    }

    // Average (r+g+b) over opaque pixels in a (2*rad+1) box around (x, y); -1 if none opaque.
    static int avgBrightness(BufferedImage img, int x, int y, int rad) {
        long sum = 0;
        int n = 0;
        for (int dx = -rad; dx <= rad; dx++) {
            for (int dy = -rad; dy <= rad; dy++) {
                int px = x + dx;
                int py = y + dy;
                if (!opaque(img, px, py)) {
                    continue;
                }
                int argb = img.getRGB(px, py);
                sum += ((argb >> 16) & 0xFF) + ((argb >> 8) & 0xFF) + (argb & 0xFF);
                n++;
            }
        }
        return n == 0 ? -1 : (int) (sum / n);
    }
}

