    private final Prayer prayer;
    private final int spriteId;

    PrayerIcon(Prayer prayer, int spriteId) {
        this.prayer = prayer;
        this.spriteId = spriteId;
    }

    boolean isEnabled(Client client) {
        return true;
    }

    // isPrayerActive(Prayer) is deprecated because it shares varbits across deadeye/eagle eye and
    // mystic vigour/might; isEnabled resolves that overlap, so the deprecation is handled, not ignored.
    @SuppressWarnings("deprecation")
    boolean isActive(Client client) {
        return client.isPrayerActive(prayer) && isEnabled(client);
    }

    private static final PrayerIcon[] VALUES = values();

    static List<Integer> activeSpriteIds(Client client) {
        List<Integer> ids = new ArrayList<>();
        for (PrayerIcon icon : VALUES) {
            if (icon.isActive(client)) {
                ids.add(icon.spriteId);
            }
        }
        return ids;
    }

    // The first n prayer sprites in table order, clamped to [0, table size]. Used by the debug
    // preview to draw a synthetic icon row without any prayers actually being active.
    static List<Integer> firstSpriteIds(int n) {
        List<Integer> ids = new ArrayList<>();
        int count = Math.min(Math.max(n, 0), VALUES.length);
        for (int i = 0; i < count; i++) {
            ids.add(VALUES[i].spriteId);
        }
        return ids;
    }
}

package com.arcvitals;

import java.awt.Color;

// Pure maths for the over-max ("overheal") band. current > max happens for hitpoints boosted past the
// real level by a Saradomin brew; the game caps every other tracked stat at its max, so they never
// trigger it. All values derive from the live current/max -- no game reads live here.
final class OverhealState {

    private OverhealState() {
    }

    // True when the live value exceeds the real maximum.
    static boolean boosted(int current, int max) {
        return max > 0 && current > max;
    }

    // The over-max slice as a fraction of the arc, measured from the full end: (current - max) / current.
    // Always in [0, 1) so the band can never recolour the whole bar. 0 when not boosted or max <= 0.
    static double overBand(int current, int max) {
        if (max <= 0 || current <= max) {
            return 0.0;
        }
        return (double) (current - max) / current;
    }

    // The band boundary as a geometric fraction (f = 0 bottom tip, f = 1 top tip) for placing the tick.
    // fillRegion measures [lo, hi] from the fill-anchored end, so the boundary sits at (1 - overBand)
    // in dir-relative terms; converting to geometric coordinates flips it for TOP_DOWN.
    static double tickGeometricFraction(double overBand, FillDirection dir) {
        double boundary = 1.0 - overBand;
        return dir == FillDirection.BOTTOM_UP ? boundary : 1.0 - boundary;
    }

    // A bright, near-opaque variant of the band colour for the real-max tick: one third band, two
    // thirds white, so it reads on any bar colour while keeping a hint of the band's hue.
    static Color tickColor(Color band) {
        int r = (band.getRed() + 255 * 2) / 3;
        int g = (band.getGreen() + 255 * 2) / 3;
        int b = (band.getBlue() + 255 * 2) / 3;
        return new Color(r, g, b, 235);
    }
}

package com.arcvitals;

// How a TaperedGeometry's half-thickness scales along its length. f = 0 is the bottom tip, f = 1 the
// top tip (independent of fill direction). Returns a scale in [0,1] applied to half the stroke width.
// Package-private: not a config return type.
enum TaperProfile {
    // Fat in the middle, tapering to a point at both tips (symmetric).
    LEAF {
        @Override
        double halfScale(double f) {
            return Math.sin(Math.PI * f);
        }
    },
    // Thick at the bottom (full) end, tapering to a narrow tip at the top (asymmetric).
    HORN {
        @Override
        double halfScale(double f) {
            return 0.16 + 0.84 * (1.0 - f);
        }
    };

    abstract double halfScale(double f);
}

package com.arcvitals;

final class BarLayout {

    private BarLayout() {
    }

    static int gapForIndex(int baseGap, int thickness, int spacing, int index) {
        return baseGap + index * (thickness + spacing);
    }

    static int labelBaselineY(int cy, int size, int fontHeight, int index) {
        return cy + size / 2 + fontHeight * (index + 1);
    }

    // The value-text anchor for one bar: {centerX, baselineY}. The overlay centres the text on
    // centerX and draws its baseline at baselineY. Non-ring shapes keep the historic placement
    // (belly column, stacked below the bar). Rings place the label just beyond each half-ring's
    // belly on its bulge side, staggered down by nesting index so concentric labels never collide.
    static int[] labelAnchor(BarShape shape, int cx, int cy, int size, int gap, int thickness,
                             int index, int fontHeight, boolean leftSide) {
        if (shape == BarShape.RING) {
            int pad = 12;
            int centerX = leftSide ? (cx - gap - thickness / 2 - pad) : (cx + gap + thickness / 2 + pad);
            int baselineY = cy + fontHeight / 3 + index * (fontHeight + 2);
            return new int[]{centerX, baselineY};
        }
        int centerX = leftSide ? (cx - gap) : (cx + gap);
        int baselineY = labelBaselineY(cy, size, fontHeight, index);
        return new int[]{centerX, baselineY};
    }
}

