import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.awt.Stroke;
import java.awt.geom.Area;
import java.awt.geom.Line2D;

// The fill-style axis: how the filled portion of a bar is painted. Public because it is a config
// return type. Inputs arrive in a FillContext: `ctx.base` is the base fill Paint (a solid colour,
// or a tinted pattern texture) and `ctx.color` is the bar's solid colour, used to derive highlights.
public enum FillStyle {

    SMOOTH("Smooth") {
        @Override
        void paint(Graphics2D g, Geometry geo, FillDirection dir, double fraction, FillContext ctx) {
            double frac = BarColors.clamp01(fraction);
            if (frac <= 0.0) {
                return;
            }
            g.setPaint(ctx.base);
            g.fill(geo.fillRegion(0.0, frac, dir));
        }
    },

    GLOSS("Glossy") {
        @Override
        void paint(Graphics2D g, Geometry geo, FillDirection dir, double fraction, FillContext ctx) {
            double frac = BarColors.clamp01(fraction);
            if (frac <= 0.0) {
                return;
            }
            Area region = geo.fillRegion(0.0, frac, dir);
            g.setPaint(ctx.base);
            g.fill(region);
            Shape oldClip = g.getClip();
            Stroke oldStroke = g.getStroke();
            g.clip(region);
            int t = geo.thickness();
            Shape cl = geo.centerline();
            strokeCenterline(g, cl, t * 0.82f, ctx.color);
            strokeCenterline(g, cl, t * 0.5f, BarColors.lighten(ctx.color, 0.26));
            strokeCenterline(g, cl, t * 0.24f, BarColors.lighten(ctx.color, 0.6));
            g.setStroke(oldStroke);
            g.setClip(oldClip);
        }
    },

    GRADIENT("Gradient") {
        @Override
        void paint(Graphics2D g, Geometry geo, FillDirection dir, double fraction, FillContext ctx) {
            double frac = BarColors.clamp01(fraction);
            if (frac <= 0.0) {
                return;
            }
            double[] anchor = geo.pointAt(dir == FillDirection.BOTTOM_UP ? 0.0 : 1.0);
            double[] far = geo.pointAt(dir == FillDirection.BOTTOM_UP ? 1.0 : 0.0);
            Color bright = BarColors.lighten(ctx.color, 0.35);
            Color dark = BarColors.scale(ctx.color, 0.5);
            if (Math.hypot(anchor[0] - far[0], anchor[1] - far[1]) < 1.0) {
                g.setPaint(ctx.base);
                g.fill(geo.fillRegion(0.0, frac, dir));
                return;
            }
            GradientPaint gp = new GradientPaint(
                (float) anchor[0], (float) anchor[1], bright,
                (float) far[0], (float) far[1], dark);
            g.setPaint(gp);
            g.fill(geo.fillRegion(0.0, frac, dir));
        }
    },

    SEGMENTED("Segmented") {
        @Override
        void paint(Graphics2D g, Geometry geo, FillDirection dir, double fraction, FillContext ctx) {
            double frac = BarColors.clamp01(fraction);
            if (frac <= 0.0) {
                return;
            }
            g.setPaint(ctx.base);
            int segs = ctx.segments;
            double cell = 1.0 / segs;
            double onFrac = 0.72; // fraction of each cell that is a pip; the rest is a gap
            for (int i = 0; i < segs; i++) {
                double a = i * cell;
                if (a >= frac) {
                    break;
                }
                double b = Math.min(a + cell * onFrac, frac);
                if (b > a) {
                    g.fill(geo.fillRegion(a, b, dir));
                }
            }
        }
    },

    GLOW("Glow") {
        @Override
        void paint(Graphics2D g, Geometry geo, FillDirection dir, double fraction, FillContext ctx) {
            double frac = BarColors.clamp01(fraction);
            if (frac <= 0.0) {
                return;
            }
            Area region = geo.fillRegion(0.0, frac, dir);
            g.setPaint(ctx.base);
            g.fill(region);
            Shape oldClip = g.getClip();
            Stroke oldStroke = g.getStroke();
            Composite oldComposite = g.getComposite();
            g.clip(region);
            Shape cl = geo.centerline();
            g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.35f));
            strokeCenterline(g, cl, geo.thickness() * 1.3f, ctx.color);
            g.setComposite(oldComposite);
            strokeCenterline(g, cl, geo.thickness() * 0.4f, BarColors.lighten(ctx.color, 0.55));
            g.setStroke(oldStroke);
            g.setClip(oldClip);
        }
    },

    NOTCHED("Notched") {
        @Override
        void paint(Graphics2D g, Geometry geo, FillDirection dir, double fraction, FillContext ctx) {
            double frac = BarColors.clamp01(fraction);
            if (frac <= 0.0) {
                return;
            }
            Area region = geo.fillRegion(0.0, frac, dir);
            g.setPaint(ctx.base);
            g.fill(region);
            Shape oldClip = g.getClip();
            Stroke oldStroke = g.getStroke();
            g.clip(region);
            g.setColor(BarColors.scale(ctx.color, 0.25));
            g.setStroke(new BasicStroke(2f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_ROUND));
            double t = geo.thickness();
            for (double f : new double[]{0.25, 0.5, 0.75}) {
                double[] p = geo.pointAt(f);
                double[] n = geo.normalAt(f);
                double hx = n[0] * (t / 2.0);
                double hy = n[1] * (t / 2.0);
                g.draw(new Line2D.Double(p[0] - hx, p[1] - hy, p[0] + hx, p[1] + hy));
            }
            g.setStroke(oldStroke);
            g.setClip(oldClip);
        }
    };

    private final String label;

    FillStyle(String label) {
        this.label = label;
    }

    abstract void paint(Graphics2D g, Geometry geo, FillDirection dir, double fraction, FillContext ctx);

    @Override
    public String toString() {
        return label;
    }

    // Draws the centreline with a round-capped stroke of the given width and colour.
    static void strokeCenterline(Graphics2D g, Shape centerline, float width, Color c) {
        g.setStroke(new BasicStroke(width, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g.setColor(c);
        g.draw(centerline);
    }
}

