package com.arcvitals;

final class BarState {

    final int current;
    final int max;
    final double fraction;
    final boolean low;

    private BarState(int current, int max, double fraction, boolean low) {
        this.current = current;
        this.max = max;
        this.fraction = fraction;
        this.low = low;
    }

    static BarState of(int current, int max, int thresholdPct) {
        double frac;
        if (max <= 0) {
            frac = 0.0;
        } else {
            frac = (double) current / max;
            if (frac < 0.0) {
                frac = 0.0;
            } else if (frac > 1.0) {
                frac = 1.0;
            }
        }
        boolean low = frac < (thresholdPct / 100.0);
        return new BarState(current, max, frac, low);
    }

    static float opacity(boolean selfLow, boolean anyLow, AlertMode mode, int basePct, int alertPct) {
        boolean alert;
        switch (mode) {
            case PER_BAR:
                alert = selfLow;
                break;
            case WHOLE_HUD:
                alert = anyLow;
                break;
            case OFF:
            default:
                alert = false;
                break;
        }
        int pct = alert ? alertPct : basePct;
        if (pct < 0) {
            pct = 0;
        } else if (pct > 100) {
            pct = 100;
        }
        return pct / 100f;
    }

    static boolean warn(BarState self, boolean warnColorEnabled) {
        return warnColorEnabled && self.low;
    }

    static double previewFraction(int current, int max, int restore) {
        if (max <= 0) {
            return 0.0;
        }
        double f = (double) (current + restore) / max;
        if (f < 0.0) {
            return 0.0;
        }
        return f > 1.0 ? 1.0 : f;
    }
}

package com.arcvitals;

import javax.inject.Singleton;
import net.runelite.api.Actor;

// Tracks the local player's current combat target for the target bar, with a short linger after
// combat so the bar does not flicker between attacks. Mirrors RuneLite's Opponent Information, but
// tick-based (like CombatTracker) for testability. All calls happen on the client thread.
@Singleton
public class TargetTracker {

    // How many idle game ticks (no interaction) to keep showing the last target. ~5s at 0.6s/tick.
    static final int LINGER_TICKS = 8;

    private Actor target;
    private int lastSeenTick;

    // From InteractingChanged when the local player is the source. A non-null opponent becomes the
    // current target; a null opponent is ignored here (the linger clear runs on the game tick).
    // This deliberately overlaps onGameTick's non-null branch: it exists only to pick up a new target
    // mid-tick rather than waiting for the next GameTick, so it is kept despite the small redundancy.
    void onInteracting(Actor opponent, int tick) {
        if (opponent != null) {
            target = opponent;
            lastSeenTick = tick;
        }
    }

    // Once per game tick. Keeps the target fresh while still interacting; otherwise clears it once the
    // linger window has elapsed.
    void onGameTick(Actor interactingNow, int tick) {
        if (interactingNow != null) {
            target = interactingNow;
            lastSeenTick = tick;
        } else if (target != null && tick - lastSeenTick > LINGER_TICKS) {
            target = null;
        }
    }

    // The target to draw, or null.
    Actor current() {
        return target;
    }

    void reset() {
        target = null;
    }
}

package com.arcvitals;

// Pure attack-cooldown maths for the swing timer. aspeed is the equipped weapon's base attack speed
// in game ticks (unarmed = 4). Ranged "Rapid" is one tick faster; melee styles do not change speed,
// so the caller passes rapid = false for them. No AWT, no Client.
final class SwingTiming {

    private SwingTiming() {
    }

    static int cooldownTicks(int aspeed, boolean rapid) {
        int ticks = rapid ? aspeed - 1 : aspeed;
        return ticks < 1 ? 1 : ticks;
    }
}

