package com.arcvitals;

import java.awt.Shape;
import java.awt.geom.Arc2D;
import java.awt.geom.Area;
import java.awt.geom.Point2D;

// Shared base for the curved bar geometries (Arc, Tapered, Ring). It owns the angular-wedge fill
// maths and the arc-derived centreline / point / normal, all of which are identical across those
// shapes. Subclasses supply only their own body() outline and set the shared circle fields via the
// constructor. Angles are Arc2D degrees (0 = east, positive counterclockwise on screen); f = 0 is
// the bottom tip and f = 1 the top tip, independent of fill direction.
abstract class CurvedGeometry implements Geometry {

    final double centerX;
    final double centerY;
    final double radius;
    final int thickness;
    final double topAngle;
    final double bottomAngle;

    // The body outline as an Area, flattened once on first fill and reused thereafter. body() is
    // immutable and the geometry is cached across frames, so the intersection target never changes.
    private Area cachedBodyArea;

    CurvedGeometry(double centerX, double centerY, double radius, int thickness,
                   double topAngle, double bottomAngle) {
        this.centerX = centerX;
        this.centerY = centerY;
        this.radius = radius;
        this.thickness = thickness;
        this.topAngle = topAngle;
        this.bottomAngle = bottomAngle;
    }

    // The full outline (tapered band, half-ring capsule, ...). Filled for the track, stroked for the
    // outline, and the intersection target for every fill region.
    @Override
    public abstract Shape body();

    @Override
    public Shape centerline() {
        double extent = topAngle - bottomAngle;
        return new Arc2D.Double(centerX - radius, centerY - radius, radius * 2.0, radius * 2.0,
            bottomAngle, extent, Arc2D.OPEN);
    }

    @Override
    public int thickness() {
        return thickness;
    }

    @Override
    public Area fillRegion(double lo, double hi, FillDirection dir) {
        if (hi <= lo) {
            return new Area();
        }
        double anchorAngle;
        double fullExtent;
        if (dir == FillDirection.BOTTOM_UP) {
            anchorAngle = bottomAngle;
            fullExtent = topAngle - bottomAngle;
        } else {
            anchorAngle = topAngle;
            fullExtent = bottomAngle - topAngle;
        }
        double sign = Math.signum(fullExtent);
        if (sign == 0.0) {
            return new Area();
        }
        // Angular width (degrees) of the stroke's end cap at this radius.
        double padDeg = Math.toDegrees((thickness / 2.0) / radius) + 0.5;
        double startDeg = anchorAngle + fullExtent * lo;
        double endDeg = anchorAngle + fullExtent * hi;
        if (lo <= 0.0) {
            startDeg -= sign * padDeg;
        }
        if (hi >= 1.0) {
            endDeg += sign * padDeg;
        }
        double r = radius + thickness; // safely beyond the body's outer edge
        Arc2D wedge = new Arc2D.Double(centerX - r, centerY - r, r * 2.0, r * 2.0,
            startDeg, endDeg - startDeg, Arc2D.PIE);
        Area area = new Area(wedge);
        area.intersect(bodyArea());
        return area;
    }

    // The cached body Area, never mutated (callers intersect a fresh wedge Area against it).
    private Area bodyArea() {
        if (cachedBodyArea == null) {
            cachedBodyArea = new Area(body());
        }
        return cachedBodyArea;
    }

    @Override
    public double[] pointAt(double f) {
        double angle = bottomAngle + (topAngle - bottomAngle) * f;
        // Read the on-screen point from an Arc2D start point to avoid flipped-Y sign mistakes.
        Arc2D probe = new Arc2D.Double(centerX - radius, centerY - radius, radius * 2.0, radius * 2.0,
            angle, 0.0, Arc2D.OPEN);
        Point2D p = probe.getStartPoint();
        return new double[]{p.getX(), p.getY()};
    }

    @Override
    public double[] normalAt(double f) {
        double[] p = pointAt(f);
        double dx = p[0] - centerX;
        double dy = p[1] - centerY;
        double len = Math.hypot(dx, dy);
        if (len < 1e-6) {
            return new double[]{1.0, 0.0};
        }
        return new double[]{dx / len, dy / len};
    }
}

package com.arcvitals;

import javax.inject.Singleton;

// Holds the swing-timer state between the plugin (which detects a swing on the client thread and
// records it) and the overlay (which reads the fill each frame). Mirrors TargetTracker/CombatTracker:
// tick-based linger, plain fields, all calls on the client/render threads. The fill is nanosecond
// wall-clock based (via SwingState) so it is smooth sub-tick.
@Singleton
public class SwingTracker {

    // How many idle game ticks to keep the timer up after the last swing. ~5s at 0.6s/tick.
    static final int LINGER_TICKS = 8;

    // A tick far below any real game tick, so "no swing yet" reads as not showing.
    private static final int NO_SWING = -1_000_000;

    private int cooldownTicks;
    private long swingNanos;
    private int lastSwingTick = NO_SWING;
    private boolean hasSwung;

    void onSwing(int cooldownTicks, int tick, long nanos) {
        this.cooldownTicks = cooldownTicks;
        this.lastSwingTick = tick;
        this.swingNanos = nanos;
        this.hasSwung = true;
    }

    void reset() {
        hasSwung = false;
        lastSwingTick = NO_SWING;
    }

    boolean showing(int currentTick) {
        return hasSwung && SwingState.showing(currentTick, lastSwingTick, LINGER_TICKS);
    }

    double fraction(long nowNanos) {
        return SwingState.fraction(elapsedMs(nowNanos), cooldownTicks);
    }

    boolean ready(long nowNanos) {
        return SwingState.ready(elapsedMs(nowNanos), cooldownTicks);
    }

    int cooldownTicks() {
        return cooldownTicks;
    }

    private long elapsedMs(long nowNanos) {
        return (nowNanos - swingNanos) / 1_000_000L;
    }
}

package com.arcvitals;

import java.awt.Shape;
import java.awt.geom.Path2D;

// A curved bar whose stroke width tapers along its length per a TaperProfile (Leaf or Horn). It
// shares the arc centreline with ArcGeometry (via ArcCenterline) and the fill/point/normal maths
// with RingGeometry (via CurvedGeometry). Its body is a filled variable-width Path2D rather than a
// constant-width stroked capsule. flatEnds does not apply (the profile shapes the tips).
final class TaperedGeometry extends CurvedGeometry {

    private static final int SAMPLES = 96;

    private final Shape body;

    TaperedGeometry(int cx, int cy, int size, int thickness, int baseGap, int spacing,
                    int curveDegrees, int index, boolean leftSide, TaperProfile profile) {
        this(new ArcCenterline(cx, cy, size, thickness, baseGap, spacing, curveDegrees, index, leftSide),
            thickness, profile);
    }

    private TaperedGeometry(ArcCenterline c, int thickness, TaperProfile profile) {
        super(c.centerX, c.centerY, c.radius, thickness, c.topAngle, c.bottomAngle);
        this.body = buildBody(profile);
    }

    private Shape buildBody(TaperProfile profile) {
        double halfT = thickness / 2.0;
        Path2D.Double p = new Path2D.Double();
        // Outer edge, f: 0 -> 1.
        for (int i = 0; i <= SAMPLES; i++) {
            double f = i / (double) SAMPLES;
            double[] pt = pointAt(f);
            double[] n = normalAt(f);
            double h = halfT * clampScale(profile.halfScale(f));
            double x = pt[0] + n[0] * h;
            double y = pt[1] + n[1] * h;
            if (i == 0) {
                p.moveTo(x, y);
            } else {
                p.lineTo(x, y);
            }
        }
        // Inner edge, f: 1 -> 0.
        for (int i = SAMPLES; i >= 0; i--) {
            double f = i / (double) SAMPLES;
            double[] pt = pointAt(f);
            double[] n = normalAt(f);
            double h = halfT * clampScale(profile.halfScale(f));
            p.lineTo(pt[0] - n[0] * h, pt[1] - n[1] * h);
        }
        p.closePath();
        return p;
    }

    private static double clampScale(double s) {
        if (s < 0.0) {
            return 0.0;
        }
        return s > 1.0 ? 1.0 : s;
    }

    @Override
    public Shape body() {
        return body;
    }
}

