package com.arcvitals;

// A synthetic oscillating percentage for the debug "Animate" preview: a triangle wave in [LOW, HIGH]
// with a per-bar phase offset so the bars do not sweep in lockstep. Pure and time-driven off a passed-
// in millisecond value (no Date/random), so the overlay stays the only place that reads the clock.
final class DebugAnimate {

    static final int LOW = 20;
    static final int HIGH = 95;
    static final long PERIOD_MS = 4000L;
    private static final long PHASE_STEP_MS = 700L;

    private DebugAnimate() {
    }

    static int percent(long nowMillis, int phaseIndex) {
        long t = Math.floorMod(nowMillis + phaseIndex * PHASE_STEP_MS, PERIOD_MS);
        double half = PERIOD_MS / 2.0;
        double tri = t < half ? t / half : (PERIOD_MS - t) / half; // ramps 0 -> 1 -> 0
        return (int) Math.round(LOW + (HIGH - LOW) * tri);
    }
}

package com.arcvitals;

import java.awt.Shape;
import java.awt.geom.Area;

// Per-bar geometry shared by every BarShape. Immutable once built. The bar runs between two
// tips; f = 0 is the geometric BOTTOM tip and f = 1 the TOP tip, independent of fill direction.
interface Geometry {

    // The full stroked outline: filled for the track, stroked for the outline, and the
    // intersection target for every fill region.
    Shape body();

    // The sub-area of body() covering the fraction band [lo, hi], measured from the anchored
    // end chosen by dir (bottom for BOTTOM_UP, top for TOP_DOWN). Empty when hi <= lo.
    Area fillRegion(double lo, double hi, FillDirection dir);

    // The centreline down the middle of the stroke, for styles that draw along the bar.
    Shape centerline();

    // Stroke width of the bar in pixels.
    int thickness();

    // On-screen point {x, y} at fraction f along the bar (f = 0 bottom tip, f = 1 top tip).
    double[] pointAt(double f);

    // Unit normal {nx, ny} at fraction f, perpendicular to the centreline, for tick orientation.
    double[] normalAt(double f);
}

package com.arcvitals;

// Pure geometry for the Alt + drag HUD move: point-in-padded-rect hit testing and per-axis offset
// with clamping. No AWT drawing, no Client, no state.
final class HudDragMath {

    private HudDragMath() {
    }

    // True when (px, py) lies inside the rectangle grown by pad on every side. A zero-area rectangle
    // (nothing drawn this frame) never registers a hit.
    static boolean hits(int x, int y, int w, int h, int pad, int px, int py) {
        if (w <= 0 || h <= 0) {
            return false;
        }
        return px >= x - pad && px <= x + w + pad && py >= y - pad && py <= y + h + pad;
    }

    // New offset for one axis: the grab-start offset plus how far the cursor has moved since the
    // grab, clamped to [min, max].
    static int axisOffset(int startOffset, int startCoord, int curCoord, int min, int max) {
        int v = startOffset + (curCoord - startCoord);
        if (v < min) {
            return min;
        }
        return v > max ? max : v;
    }
}

